#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>ratio={1.1,1.4,0.7},advantage={1,-1,0.5};
double clip=0.2,total=0;
for(int i=0;i<int(ratio.size());i++){
    double clipped=max(1-clip,min(1+clip,ratio[i]));
    double surrogate=min(ratio[i]*advantage[i],clipped*advantage[i]);
    total+=surrogate/ratio.size();
}
cout<<"PPO clipped objective "<<total<<"
";
return 0;
}

